  "loc.enterInternetConnectionsAddress": "Wpisz adres swojego łącza internetowego jako serwer (np. adres MyFRITZ!) – zwykle poleceniem SMS według instrukcji lokalizatora.",
  "loc.enterShopAddressesUnder": "Adresy sklepów wpisujesz w Listy → Edytuj listę zakupów – jeśli sklep istnieje w kilku miejscach, także kilka oddziałów. Jeśli ktoś zostanie tam dłużej, zaplanowane zakupy zostaną odznaczone.",
