  "loc.familyGetsMessageSees#wg": "Wspólne mieszkanie dostaje wiadomość i widzi twoją lokalizację na żywo, dopóki nie dotrzesz do domu. Ruszamy?",
  "loc.familySeesLiveDuration": "Rodzina widzi cię na żywo na mapie – z ustawionym czasem kończy się samo.",
