  "loc.fields": "Pola: {felder}",
  "loc.fromPinn": "z pinn.",
  "loc.fromTraccar": "z „Traccar Client”",
  "loc.gettingLocation": "Ustalanie lokalizacji …",
  "loc.gpsTracker": "🛰️ Lokalizator GPS",
  "loc.guide1": "Zainstaluj aplikację <b>„Traccar Client”</b> (App Store lub Google Play, darmowa).",
  "loc.guide2": "W aplikacji wpisz w polu <b>Device ID</b> (identyfikator urządzenia):",
  "loc.guide3": "W polu <b>Server URL</b> wpisz:",
  "loc.guide4": "Dokładność <b>Medium</b>, dystans <b>50 m</b>. Aplikacja wysyła wtedy tylko podczas ruchu – nic, gdy stoisz. Jeśli masz więcej pól (interwał, heartbeat), ustaw heartbeat na wyłączony lub 0.",
  "loc.guide5": "Zezwól na dostęp do lokalizacji: <b>Zawsze</b> i włącz <b>Dokładną lokalizację</b>.",
  "loc.guide6": "Włącz przełącznik <b>Service / Tracking</b> i <b>zawsze zostaw go włączony</b> – gotowe. Odtąd wszystkim sterujesz w pinn.: „Wysyłaj stale” włączone lub wyłączone, „Wyślij raz” i SOS. Dopóki „Wysyłaj stale” jest wyłączone, nikt nie widzi twojej lokalizacji, a pinn. nie zapisuje trasy.",
  "loc.guideIntro": "Bez dodatkowej aplikacji „📍 Udostępnij lokalizację” działa bezpośrednio w pinn. – ale tylko, gdy pinn. jest otwarte. Aby lokalizacja docierała także przy zamkniętym pinn. i zablokowanym ekranie, darmowa aplikacja „Traccar Client” wysyła ją bezpośrednio do pinn. (serwer Traccar nie jest potrzebny). Tak samo na iPhonie i Androidzie.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. Ten port trzeba przekierować do NAS-a w FRITZ!Box, ponieważ lokalizator łączy się z sieci komórkowej.",
  "loc.haveGoodTripFamily": "Szerokiej drogi! Rodzina została poinformowana.",
