  "loc.setup": "Konfiguracja · {famDeviceName}",
  "loc.setupIntro": "Telefony nie potrzebują niczego więcej: każdy może udostępniać bezpośrednio w pinn. w „Moja lokalizacja”. W tle (przy zamkniętym pinn.) telefon wysyła przez darmową aplikację „Traccar Client” (iPhone i Android) – bezpośrednio do pinn., serwer Traccar nie jest potrzebny. Tylko lokalizatory GPS z kartą SIM (np. na obroży) potrzebują kontenera „traccar”. Lokalizacje zostają na twoim NAS-ie.",
