  "loc.testSameProcessReal#wg": "Test: ten sam przebieg co przy prawdziwym wezwaniu pomocy (push, okno, mapa, adres) – ale tylko do ciebie, wspólne mieszkanie niczego nie zauważa.",
  "loc.tipSetAddressUnder": "Wskazówka: ustaw swój adres w Ustawienia → Dom – wtedy automatycznie powstaje miejsce „Dom” z powiadomieniem push przy przybyciu i wyjściu.",
  "loc.traccarClientChooseSend": "W „Traccar Client” wybierz „Send SOS” (zależnie od wersji w aplikacji lub przez długie przytrzymanie ikony aplikacji). pinn. natychmiast alarmuje wszystkich członków rodziny przez push – z lokalizacją, adresem, godziną i przyciskami do połączenia i numeru alarmowego {regionNotrufText}. Wskazówka: wpisz własny numer komórkowy w karcie alarmowej.",
  "loc.traccarClientChooseSend#wg": "W „Traccar Client” wybierz „Send SOS” (zależnie od wersji w aplikacji lub przez długie przytrzymanie ikony aplikacji). pinn. natychmiast alarmuje wszystkich współlokatorów przez push – z lokalizacją, adresem, godziną i przyciskami do połączenia i numeru alarmowego {regionNotrufText}. Wskazówka: wpisz własny numer komórkowy w karcie alarmowej.",
