  "settings.calendar.info": "Każdy profil loguje się własnym kontem iCloud lub Google i zaznacza z niego kalendarze: „Dla mnie” widzi tylko twój własny profil, „Rodzina” widzą i używają wszyscy w twojej rodzinie. Pozostali widzą tylko, z jakiego konta pochodzi kalendarz rodzinny – w zasłoniętej formie, np. m**l@g***l.com. Wydarzenia można jak zwykle tworzyć, edytować, przenosić i kolejkować offline, a trafiają bezpośrednio do iCloud lub Google (a więc na telefon). Synchronizacja co 15 minut lub przez „Aktualizuj teraz”. Bez konta działa też kalendarz tylko na twoim serwerze pinn. Przypomnienia i codzienne podsumowanie jako push: wydarzenia prywatne tylko dla ciebie.",
  "settings.calendar.info#wg": "Każdy profil loguje się własnym kontem iCloud lub Google i zaznacza z niego kalendarze: „Dla mnie” widzi tylko twój własny profil, „Wspólne mieszkanie” widzą i używają wszyscy w twoim wspólnym mieszkaniu. Pozostali widzą tylko, z jakiego konta pochodzi kalendarz wspólny – w zasłoniętej formie, np. m**l@g***l.com. Wydarzenia można jak zwykle tworzyć, edytować, przenosić i kolejkować offline, a trafiają bezpośrednio do iCloud lub Google (a więc na telefon). Synchronizacja co 15 minut lub przez „Aktualizuj teraz”. Bez konta działa też kalendarz tylko na twoim serwerze pinn. Przypomnienia i codzienne podsumowanie jako push: wydarzenia prywatne tylko dla ciebie.",
