  "settings.outlook.intro": "W każdą niedzielę od godz. 18:00 pojawia się podgląd tygodnia ze wszystkim, co ważne dla rodziny w nadchodzącym tygodniu, a w ostatni dzień miesiąca od godz. 18:00 – zapowiedź finansów na następny miesiąc. Obie pojawiają się raz jako komunikat na górze i jako powiadomienie push – możesz je tu w każdej chwili otworzyć ponownie.",
