  "smart.guide1": "1. Nowy skrót „pinn Automatik”:",
  "smart.guide10": "Urządzenie musi do tego dosięgać pinn. (Wi-Fi w domu lub VPN). Każda akcja działa tylko raz na zadanie; to, co już uruchomiono przyciskiem, nie jest uruchamiane ponownie przez automatyzację.",
  "smart.guide2": "• „Pobierz zawartość adresu URL” – wklej powyższy link",
