  "smart.guide5": "– „Pobierz wartość ze słownika” – klucz „eingabe” z „Elementu powtórzenia”",
  "smart.guide6": "– „Pobierz wartość ze słownika” – klucz „kurzbefehl” z „Elementu powtórzenia”",
  "smart.guide7": "– „Uruchom skrót” – wybierz wartość „kurzbefehl” jako skrót, a wartość „eingabe” jako dane wejściowe",
  "smart.guide8": "2. Zakładka „Automatyzacja” → „Pora dnia” – jedna automatyzacja na każdą godzinę u góry, „Uruchom natychmiast” → „pinn Automatik”.",
  "smart.guide9": "3. Wskazówka: dodatkowo „Przybycie” (Dom) → „pinn Automatik” – nadrabia to, co pominięto.",
  "smart.haAddress": "Adres",
  "smart.haAddressHint": "Po prostu adres IP tak, jak wpisujesz go w przeglądarce – pinn. samo próbuje http://, https:// i portu (8123). „homeassistant.local” tutaj nie działa, użyj IP (Home Assistant → Ustawienia → System → Sieć lub w routerze).",
