  "smart.haDevices": "Urządzenia przez Home Assistant: {list}",
  "smart.haIntro": "Serwer pinn. steruje Home Assistant bezpośrednio – przyciski działają na każdym urządzeniu (także Androidzie), automatyzacja i „Przy odznaczeniu” działają bez skrótów. Z encją stanu pinn. czeka, aż np. odkurzacz automatyczny naprawdę skończy.",
  "smart.haNeedAddress": "Podaj adres.",
