  "smart.haOn": "Home Assistant połączony",
  "smart.haSearching": "Szukanie Home Assistant …",
  "smart.haTip1": "Roborock: utwórz urządzenie „Odkurzacz automatyczny”, wybierz powyżej robota (vacuum.…) – pinn. załaduje pokoje z mapy. Dla każdej akcji „Sprzątanie pokoi” z pokojami i trybem (odkurzanie, odkurzanie i mopowanie, mopowanie). „Pokój zadania” używa pokoju z zadania sprzątania – nazwy muszą być takie same jak w aplikacji Roborock.",
  "smart.haTip2": "Robot służy też jako stan: następna akcja startuje dopiero, gdy wróci do stacji.",
  "smart.haTip3": "Skrypty dostają nazwę pokoju jako zmienną <span class=\"font-mono\">raum</span> – dzięki temu jeden skrypt obsłuży wszystkie pokoje.",
  "smart.haTip4": "Światła/diody: kolor i jasność ustaw bezpośrednio w akcji.",
  "smart.haTip5": "Automatyzacja działa na serwerze co minutę – na telefonie nie jest potrzebna żadna automatyzacja.",
  "smart.haToken": "Długoterminowy token dostępu",
  "smart.haTokenHint": "W Home Assistant: w lewym dolnym rogu na swoim profilu → zakładka „Zabezpieczenia” → „Długoterminowe tokeny dostępu” → „Utwórz token” i wklej cały długi ciąg. Nie musisz wpisywać z przodu „Bearer” – pinn. dodaje to samo (nie szkodzi też, jeśli wpiszesz). Token zostaje na serwerze i nigdy nie jest wysyłany do urządzeń.",
